#pragma once

#include "stageviz.h"
#include <pxr/base/tf/token.h>
#include <pxr/usd/sdf/path.h>

namespace stageviz::paths::auxiliary {

/**
 * @brief Root of viewport-only geometry in the auxiliary USD stage.
 *
 * Geometry under /Display is generated by Stageviz for viewport presentation.
 * It is separate from the user's document stage and is not saved with it.
 * Individual children may be rendered in different passes.
 */
inline const pxr::SdfPath display { "/Display" };

/**
 * @brief Root of materials used by Stageviz's auxiliary rendering features.
 *
 * Contains materials for viewport helpers and visualization effects, rather
 * than materials authored in the user's document stage.
 */
inline const pxr::SdfPath materials { "/Materials" };

/**
 * @brief Viewport reference grid under /Display/Grid.
 *
 * Rendered as auxiliary scene geometry, using the normal grid/display pass.
 */
inline const pxr::SdfPath grid = display.AppendChild(pxr::TfToken("Grid"));

/**
 * @brief 3D transform handles under /Display/TransformGizmo.
 *
 * Contains the move, rotate, and scale handle geometry. Rendered in a
 * foreground pass so the handles remain visible over document geometry.
 * The central 2D pivot marker is drawn separately by the viewport overlay.
 */
inline const pxr::SdfPath transform = display.AppendChild(pxr::TfToken("Transform"));

}  // namespace stageviz::paths::auxiliary
